 let tagF='', quoteOf=null, pollOn=false, isOwner=false; setTimeout(async()=>{ try{ isOwner=!!(user&&await user.isOwner()); }catch(_){ } },2500);
 const W=()=>Object.assign({posts:[],likes:[],saved:[],muted:[],blocked:[],votes:{},reports:[]},wall||{});
