 const hidden=id=>id!==uid&&(W().muted.includes(id)||W().blocked.includes(id)||((walls[id]||{}).blocked||[]).includes(uid));
 const tagsOf=t=>(String(t||'').match(/#[A-Za-z0-9_]{2,30}/g)||[]).map(x=>x.slice(1).toLowerCase());
