 function trending(){ const c={}, since=Date.now()-7*864e5; Object.entries(Object.assign({},walls,{[uid]:W()})).forEach(([id,w])=>{ if(hidden(id)) return; (w.posts||[]).forEach(p=>{ if((p.at||0)<since) return; tagsOf(p.text).forEach(t=>c[t]=(c[t]||0)+1); }); }); return Object.entries(c).sort((a,b)=>b[1]-a[1]).slice(0,10); }
