 function votesFor(by,pid,n){ const c=Array(n).fill(0); Object.values(Object.assign({},walls,{[uid]:W()})).forEach(w=>{ const v=(w.votes||{})[by+':'+pid]; if(v!=null&&v<n) c[v]++; }); return c; }
 function pollHTML(p){ if(!p.poll||!Array.isArray(p.poll.opts)) return ''; const n=p.poll.opts.length, c=votesFor(p.by,p.id,n), tot=c.reduce((a,b)=>a+b,0), mine=W().votes[p.by+':'+p.id]; return '<div class="kaPoll">'+p.poll.opts.map((o,i)=>{ const pc=tot?Math.round(c[i]*100/tot):0; return '<button type="button" data-ka="vote" data-by="'+esc(p.by)+'" data-pid="'+esc(p.id)+'" data-i="'+i+'" data-noul style="background:linear-gradient(90deg,rgba(42,212,255,.35) '+pc+'%,rgba(255,255,255,.04) '+pc+'%)!important">'+(mine===i?'✅ ':'')+esc(o)+' <span class="kaNote">'+pc+'%</span></button>'; }).join('')+'<div class="kaNote">'+tot+' vote'+(tot===1?'':'s')+'</div></div>'; }
