 function storiesHTML(){ const S=stories(), ids=Object.keys(S); if(!ids.length) return ''; return '<div class="kaStories">'+ids.map(id=>{ const n=nameOf(id); return '<button type="button" data-ka="story" data-id="'+esc(id)+'" data-noul><span class="kaRing">'+esc(n.av)+'</span><small>'+esc(id===uid?'Your story':n.name)+'</small></button>'; }).join('')+'</div>'; }
 let storyT=0; function showStory(id,i){ clearTimeout(storyT); const L=stories()[id]||[]; const p=L[i]; let v=$('kaStory'); if(!p){ if(v) v.remove(); return; } if(!v){ v=document.createElement('div'); v.id='kaStory'; $('kAcct').appendChild(v); v.addEventListener('click',e=>{ const b=e.target.closest('[data-st]'); if(!b) return; e.stopPropagation(); const a=b.dataset.st; if(a==='x'){ clearTimeout(storyT); v.remove(); return; } showStory(v.dataset.id,(+v.dataset.i)+(a==='n'?1:-1)); }); }
  v.dataset.id=id; v.dataset.i=i; const n=nameOf(id); v.innerHTML='<div class="kaStoryIn"><div class="kaBars">'+L.map((_,j)=>'<i class="'+(j<i?'done':j===i?'on':'')+'"></i>').join('')+'</div><div class="who">'+esc(n.av)+' '+esc(n.name)+' <span class="kaNote">'+ago(p.at)+'</span></div><div class="t" style="font-size:20px">'+linkTags(esc(p.text))+'</div>'+(p.media?mediaTag(p.media.type,p.media.url):'')+'<div class="kaRow"><button type="button" data-st="p" data-noul>◀</button><button type="button" data-st="n" data-noul>▶</button><button type="button" data-st="x" data-noul>✕ Close</button></div></div>'; storyT=setTimeout(()=>showStory(id,i+1),6000); }
