 const ageOf=P=>{ if(!P.showAge||!P.byear||!P.birth) return ''; const d=new Date(); const [m,dd]=String(P.birth).split('-').map(Number); let a=d.getFullYear()-(+P.byear); if(d.getMonth()+1<m||(d.getMonth()+1===m&&d.getDate()<dd)) a--; return a>0&&a<120?String(a):''; };
 function profDetails(P){ const L=[['📍','Lives in',P.location],['🏠','From',P.hometown],['🎂','Age',ageOf(P)],['⚧','Gender',P.gender],['💬','Pronouns',P.pronouns],['💼','Work',P.work],['🎓','School',P.school],['🗣','Languages',P.langs],['💞','Relationship',P.rel]].filter(x=>x[2]);
  const w=typeof P.website==='string'&&P.website.startsWith('https://')?'<a href="'+esc(P.website)+'" target="_blank" rel="noopener">🔗 '+esc(P.website.replace(/^https:\/\//,'').slice(0,40))+'</a>':'';
  return L.length||w?'<div class="kaDet">'+L.map(([i,l,v])=>'<span title="'+l+'">'+i+' '+esc(v)+'</span>').join('')+w+'</div>':''; }
 const friendsOf=id=>{ const mine=((people[id]||(id===uid?acct:{}))||{}).following||[]; return mine.filter(x=>((people[x]||{}).following||[]).includes(id)); };
