 async function shrink(file,maxW,maxH,crop){ const url=URL.createObjectURL(file); try{ const img=await new Promise((res,rej)=>{ const i=new Image(); i.onload=()=>res(i); i.onerror=rej; i.src=url; }); let sw=img.width, sh=img.height, sx=0, sy=0; if(crop){ const r=maxW/maxH; if(sw/sh>r){ const nw=sh*r; sx=(sw-nw)/2; sw=nw; } else { const nh=sw/r; sy=(sh-nh)/2; sh=nh; } }
   const sc=Math.min(1,maxW/sw,maxH/sh); const c=document.createElement('canvas'); c.width=Math.round(sw*sc); c.height=Math.round(sh*sc); c.getContext('2d').drawImage(img,sx,sy,sw,sh,0,0,c.width,c.height); return c; } finally{ URL.revokeObjectURL(url); } }
 async function onFile(e){ const inp=e.target; if(!inp||!inp.dataset.up||!form) return; const f=inp.files&&inp.files[0]; if(!f) return; if(!/^image\//.test(f.type)) return say('Pick a picture file (JPG, PNG or WebP).'); const isCover=inp.dataset.up==='cover';
  try{ say('📷 Getting your picture ready…'); const c=await shrink(f,isCover?1200:400,isCover?400:400,true); const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.85)); let url='';
   try{ assets=assets||await claude.use('assets'); if(assets&&blob){ const r=await assets.upload(blob); if(r&&r.url) url=r.url; } }catch(_){ url=''; }
   if(!url){ const s=await shrink(f,isCover?600:160,isCover?200:160,true); url=s.toDataURL('image/jpeg',.72); }
   form[isCover?'cover':'photo']=url; render(); say(isCover?'🖼 Cover ready. Save to keep it.':'📷 Photo ready. Save to keep it.'); }catch(_){ say('That picture did not load. Try another.'); } }
